from pathlib import Path
import json

TARGET="DEV-PRED-A2Z-N1E36-ASSERT-PREBUILD-BINDING-20261007-N1E40"
p=Path.home()/".local/state/prediction-project-executor"/(TARGET+".json")
if not p.is_file():
    raise RuntimeError("N1E40_STATE_MISSING")
o=json.loads(p.read_text(encoding="utf-8"))
for k in ("task_id","status","error","operations","operation_results","results","completed_at_utc","head_after","source_commit"):
    if k in o:
        s=json.dumps(o[k],ensure_ascii=False,sort_keys=True)
        if len(s)>16000: s=s[:16000]+"...<TRUNCATED>"
        print(k.upper()+"="+s)
# Also print any string leaf that looks like traceback/error, bounded.
def walk(v,path=""):
    if isinstance(v,dict):
        for k,x in v.items():
            np=(path+"."+k) if path else k
            walk(x,np)
    elif isinstance(v,list):
        for i,x in enumerate(v):
            walk(x,f"{path}[{i}]")
    elif isinstance(v,str):
        low=v.lower()
        if "traceback" in low or "runtimeerror" in low or "assert" in low or "error" in path.lower():
            print("LEAF="+path+"="+v[:12000].replace("\n"," | "))
walk(o)
